// The form gives one item holding all uploaded files. Make one item per file so each can be read.
const out = [];
for (const item of $input.all()) {
  for (const file of Object.values(item.binary || {})) {
    out.push({ json: { file: file.fileName }, binary: { data: file } });
  }
}
if (!out.length) throw new Error('No files uploaded');
return out;

